async function buildAggregatedToolList(clients) {
  const all = [];
  for (const [serverName, client] of Object.entries(clients)) {
    const { tools } = await client.listTools();
    for (const t of tools) {
      all.push({ ...t, serverName, qualifiedName: serverName + "." + t.name });
    }
  }
  return all;
}

